let ACCOUNT={user:null,settings:{},events:[]},BOOKS=[],sessionIndex=0,activeSession=[],sessionKey='',sessionCounts={},sessionFinished=false,accountFetch=null;
const lang=()=>read('language','ar');
const t=(arText,enText)=>lang()==='en'?enText:arText;
const todayKey=(zone=read('plan',{}).timezone||Intl.DateTimeFormat().resolvedOptions().timeZone)=>new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function localEvents(){return read('activity',[])}
async function api(path,body){const response=await fetch('/api/account'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,credentials:'same-origin'});if(!response.ok)throw Error(response.status);return response.json()}
async function loadAccount(){if(accountFetch)return accountFetch;accountFetch=api('').then(data=>{ACCOUNT=data;ACCOUNT.settings??={};ACCOUNT.events??=[];if(ACCOUNT.user&&ACCOUNT.settings.pages)write('plan',ACCOUNT.settings);if(ACCOUNT.user&&!sessionStorage.getItem('sakinah-visit-'+ACCOUNT.user.id)){sessionStorage.setItem('sakinah-visit-'+ACCOUNT.user.id,'1');recordActivity('login',{})}return data}).catch(()=>ACCOUNT);return accountFetch}
function recordActivity(kind,payload){const event={kind,payload,createdAt:Date.now(),eventId:crypto.randomUUID()};if(ACCOUNT.user){api('',event).then(()=>ACCOUNT.events.unshift(event)).catch(()=>{const pending=read('pendingEvents-'+ACCOUNT.user.id,[]);pending.push(event);write('pendingEvents-'+ACCOUNT.user.id,pending.slice(-200));toast(t('حُفظ النشاط على الجهاز؛ ستُعاد المزامنة عند الاتصال.','Activity saved locally; sync will retry when online.'))})}else{const events=localEvents();events.unshift(event);write('activity',events.slice(0,2500))}return event}
async function flushPending(){if(!ACCOUNT.user)return;const items=read('pendingEvents-'+ACCOUNT.user.id,[]),remaining=[];for(const event of items){try{await api('',event)}catch{remaining.push(event)}}write('pendingEvents-'+ACCOUNT.user.id,remaining)}
function finishDhikr(d){recordActivity('dhikr',{id:d.id,title:d.title,count:dhikrGoal(d)});if(read('autoAdvance',true)&&currentRoute!=='session'){const cards=[...document.querySelectorAll('.dhikr-card')],index=cards.findIndex(c=>c.id==='item-'+d.id),next=cards.slice(index+1).find(c=>{const item=LIBRARY.find(d=>'item-'+d.id===c.id);return item&&(counts[item.id]||0)<dhikrGoal(item)});if(next){setTimeout(()=>{next.scrollIntoView({behavior:'smooth',block:'center'});next.querySelector('[data-count]')?.focus({preventScroll:true})},250)}}}
function savePageCloud(page){write('savedPage',page);if(ACCOUNT.user)api('',{kind:'settings',settings:{savedPage:page}}).then(r=>ACCOUNT.settings=r.settings).catch(()=>toast(t('العلامة محفوظة على الجهاز؛ تعذرت المزامنة.','Bookmark saved on this device; sync unavailable.')))}
const baseHome=home;home=function(){baseHome();const day=Number(todayKey('Asia/Muscat').replaceAll('-','')),wisdom=[['كل خطوة صغيرة في الخير تستحق أن تبدأها اليوم.','Every small step toward good is worth beginning today.'],['اجعل لك من الهدوء وقتًا، ومن الشكر عادة، ومن الخير أثرًا.','Make time for stillness, gratitude a habit, and goodness your legacy.'],['الكلمة الطيبة صدقة، فاجعل حديثك بابًا للرحمة.','A kind word is charity; let your words open a door to compassion.'],['لا تنتظر فراغ يومك لتذكر الله؛ زيّن يومك بذكره.','Do not wait for an empty day to remember Allah; fill your day with remembrance.'],['أحسن إلى الناس بما تستطيع، ولو بابتسامة صادقة.','Offer others what kindness you can, even a sincere smile.'],['التدبر يفتح للآية بابًا في القلب، فاقرأ على مهل.','Reflection opens a place in the heart for each verse; read with care.'],['قليل يستمر خير من كثير تنقطع عنه.','A little you sustain is better than much you abandon.']][day%7];const hero=$('.hero');hero.insertAdjacentHTML('afterend',`<section class="wisdom-card"><span>✦ ${t('وقفة اليوم','Today’s reflection')}</span><p>${t(...wisdom)}</p><small>${t('نصيحة تحريرية من سكينة؛ ليست حديثًا نبويًا.','An editorial reflection from Sakinah, not a prophetic narration.')}</small></section><div class="quick-services"><a href="#account">◉ ${t('وردي ومتابعتي','My daily practice')}</a><a href="#calendar">◷ ${t('التقويم ومواقيت الصلاة','Calendar & prayer times')}</a><a href="#library">◫ ${t('مكتبة الكتب والبطاقات','Books & reading cards')}</a></div>`)};
const baseCollection=collection;collection=function(r,c='الكل'){baseCollection(r,c);const title=$('.page-heading');title.insertAdjacentHTML('afterend',`<div class="session-toolbar"><a class="btn" href="#session/${r}/${encodeURIComponent(c)}">${t('قراءة متتابعة كالسلايدات','Read as slides')} ←</a><button class="chip" id="collection-pdf">↓ PDF</button><button class="chip" id="collection-share">${t('مشاركة النصوص','Share texts')}</button><label class="auto-option"><input id="auto-next" type="checkbox" ${read('autoAdvance',true)?'checked':''}> ${t('انتقل تلقائيًا للذكر التالي','Automatically advance to the next dhikr')}</label></div>`);$('#auto-next').onchange=e=>write('autoAdvance',e.target.checked);const items=collectionItems(r,c);$('#collection-pdf').onclick=()=>openPrint(items,NAV.find(n=>n[0]===r)?.[2]||r);$('#collection-share').onclick=()=>shareText(items.map(d=>textOf(d)+'\n'+d.reference).join('\n\n'),t('ورد سكينة','Sakinah reading'))};
