const baseRenderBook=renderBook;renderBook=function(value){baseRenderBook(value);if(!$('#book'))return;const p=Number($('#book').dataset.page);$('.book-toolbar').insertAdjacentHTML('beforeend',`<a class="chip" href="#quran-scroll/${p}">↕ ${t('تمرير طولي','Vertical scroll')}</a>`);$('#book-status').insertAdjacentHTML('afterend',`<button class="chip" id="mark-page-read">✓ ${t('أنهيت قراءة هذه الصفحة','Mark this page as read')}</button>`);$('#mark-page-read').onclick=()=>markPageRead(p);document.querySelectorAll('[data-save-page]').forEach(b=>b.addEventListener('click',()=>savePageCloud(Number(b.dataset.savePage))));const saved=ACCOUNT.user&&ACCOUNT.settings.savedPage;if(saved&&!$('.cloud-bookmark'))$('.book-toolbar').insertAdjacentHTML('afterend',`<a class="saved-page cloud-bookmark" href="#quran/page/${saved}">◆ ${t('علامة حسابك','Account bookmark')}: ${ar(saved)}</a>`)};
function markPageRead(p){const key=todayKey()+':'+p,readingKey='readPages-'+(ACCOUNT.user?.id||'guest'),recorded=read(readingKey,[]);if(recorded.includes(key)){toast(t('سجلت قراءة هذه الصفحة اليوم بالفعل.','This page is already recorded for today.'));return}recorded.push(key);write(readingKey,recorded.slice(-5000));recordActivity('page',{page:p});toast(t('سُجّلت الصفحة ضمن وردك اليومي.','Page added to your daily reading.'))}
