function calendarReminder(){const plan=read('plan',{reminder:'07:00',timezone:'Asia/Muscat'}),date=new Intl.DateTimeFormat('en-CA',{timeZone:plan.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()).replaceAll('-',''),time=(plan.reminder||'07:00').replace(':','')+'00';const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Sakinah//Daily Practice//AR','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+crypto.randomUUID()+'@sakinah','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').split('.')[0]+'Z','DTSTART;TZID='+plan.timezone+':'+date+'T'+time,'DURATION:PT15M','RRULE:FREQ=DAILY','SUMMARY:ورد سكينة - Sakinah daily practice','DESCRIPTION:Quran and dhikr - '+location.origin+'/site/index.html','BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:Sakinah daily practice','END:VALARM','END:VEVENT','END:VCALENDAR'];downloadBlob(new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'}),'sakinah-daily-reminder.ics')}
function checkReminders(){const plan=read('plan',null);if(!plan)return;const time=new Intl.DateTimeFormat('en-GB',{timeZone:plan.timezone,hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()),day=todayKey(plan.timezone);if(time>=plan.reminder&&read('remindedDay','')!==day){const events=(ACCOUNT.user?ACCOUNT.events:localEvents()).filter(e=>new Intl.DateTimeFormat('en-CA',{timeZone:plan.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(e.createdAt))===day),pages=new Set(events.filter(e=>e.kind==='page').map(e=>e.payload.page)).size,dhikr=events.filter(e=>e.kind==='dhikr').reduce((n,e)=>n+(e.payload.count||0),0);if(pages>=(plan.pages||2)&&dhikr>=(plan.dhikr||100)){write('remindedDay',day);return}write('remindedDay',day);const title=t('حان وقت وردك في سكينة','Time for your Sakinah practice');toast(title);if('Notification'in window&&Notification.permission==='granted')new Notification(title,{body:t('آية وذكر ودعاء… لحظات تطمئن بها الروح.','Quran, remembrance and prayer — a moment for your heart.'),icon:new URL('assets/sakinah-emblem.png',location.href).href})}}
function sessionPage(section='athkar',category='الكل'){activeSession=collectionItems(section,category);sessionKey=section+'|'+category;sessionCounts=read('session-'+sessionKey,{});sessionFinished=activeSession.length>0&&activeSession.every(d=>(sessionCounts[d.id]||0)>=dhikrGoal(d));const startId=new URLSearchParams((location.hash.split('?')[1]||'')).get('id');const startAt=startId?activeSession.findIndex(d=>d.id===startId):-1;sessionIndex=startAt>=0?startAt:Math.max(0,activeSession.findIndex(d=>(sessionCounts[d.id]||0)<dhikrGoal(d)));if(startAt>=0)sessionFinished=false;if(!activeSession.length){$('#main').innerHTML=heading(t('وردك المتتابع','Reading session'),t('لا توجد نصوص في هذا التصنيف.','There are no texts in this category.'));return}renderSessionSlide()}
function renderSessionSlide(){if(sessionFinished){$('#main').innerHTML=heading(t('أتممت وردك، تقبّل الله منك','Your practice is complete'),t('أُضيفت الأذكار المكتملة إلى سجلّك.','Completed dhikr has been added to your activity.'))+`<div class="session-finished"><span>۞</span><button class="btn" id="restart-session">${t('بدء ورد جديد','Start a new session')}</button><a class="btn secondary" href="#account">${t('عرض متابعتي','View my progress')}</a></div>`;$('#restart-session').onclick=()=>{sessionCounts={};write('session-'+sessionKey,{});sessionIndex=0;sessionFinished=false;renderSessionSlide()};return}const d=activeSession[sessionIndex],goal=dhikrGoal(d),count=sessionCounts[d.id]||0,section=sessionKey.split('|')[0],listHref=`#${section}?view=list`;$('#main').innerHTML=heading(t('وردك… ذكرًا بعد ذكر','One remembrance at a time'),t('اقرأ النص، واضغط مع كل تكرار. ينتقل الورد تلقائيًا بعد اكتمال العدد.','Read the text and tap for each repetition. Your session advances when the count is complete.'))+`<div class="slide-meta"><a class="chip" href="${listHref}">→ ${t('القائمة','List')}</a><span>${ar(sessionIndex+1)} / ${ar(activeSession.length)}</span><label class="auto-option"><input id="slide-auto" type="checkbox" ${read('autoAdvance',true)?'checked':''}>${t('انتقال تلقائي','Auto advance')}</label></div><article class="prayer-slide"><div class="eyebrow">${esc(d.category)}</div><h2>${esc(d.title)}</h2><p class="arabic-text" lang="ar" dir="rtl">${esc(textOf(d))}</p><p class="source">${esc(d.reference)}</p><button class="bead-button slide-counter" id="slide-count" aria-label="${t('عدّ الذكر','Count dhikr')}" style="--progress:${Math.min(100,count/goal*100)}%"><strong>${ar(count)}</strong><small>${count>=goal?t('اكتمل ✓','Complete ✓'):t('اضغط مع كل ذكر','Tap with each repetition')}</small></button><p class="counter-caption">${counterLabel(d)}: ${ar(goal)}</p><div class="toolbar"><button class="chip" id="slide-share">${t('مشاركة النص','Share text')}</button><button class="chip" id="slide-file">${t('مشاركة ملف الورد','Share practice file')}</button><button class="chip" id="slide-reset">↺ ${t('إعادة العدّ','Reset count')}</button></div></article><div class="slide-navigation"><button class="btn secondary" id="slide-prev" ${sessionIndex===0?'disabled':''}>→ ${t('السابق','Previous')}</button><button class="btn" id="slide-next">${sessionIndex===activeSession.length-1?t('إنهاء','Finish'):t('التالي','Next')} ←</button></div>`;document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===section;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});$('#slide-auto').onchange=e=>write('autoAdvance',e.target.checked);$('#slide-prev').onclick=()=>{sessionIndex--;renderSessionSlide()};$('#slide-next').onclick=()=>{if(sessionIndex<activeSession.length-1){sessionIndex++;renderSessionSlide()}else{sessionFinished=true;renderSessionSlide()}};const tapSlide=()=>{if((sessionCounts[d.id]||0)>=goal){if(read('autoAdvance',true)){if(sessionIndex<activeSession.length-1){sessionIndex++;renderSessionSlide()}else{sessionFinished=true;renderSessionSlide()}}else toast(t('اكتمل العدد. استخدم التالي أو أعد العد.','Count complete. Continue or reset.'));return}sessionCounts[d.id]=(sessionCounts[d.id]||0)+1;const n=sessionCounts[d.id],btn=$('#slide-count');if(btn){btn.querySelector('strong').textContent=ar(n);btn.style.setProperty('--progress',n/goal*100+'%');btn.classList.toggle('complete',n>=goal)}queueMicrotask(()=>write('session-'+sessionKey,sessionCounts));if(n===goal){recordActivity('dhikr',{id:d.id,title:d.title,count:goal});$('#slide-count small').textContent=t('اكتمل ✓','Complete ✓');if(read('autoAdvance',true)){const at=sessionIndex;setTimeout(()=>{if(currentRoute!=='session'||sessionIndex!==at)return;if(sessionIndex<activeSession.length-1)sessionIndex++;else sessionFinished=true;renderSessionSlide()},550)}}};$('#slide-count').onclick=tapSlide;$('#slide-count').onpointerdown=e=>{if(e.button)return;e.preventDefault();tapSlide()};$('#slide-share').onclick=()=>shareText(textOf(d)+'\n'+d.reference,d.title);$('#slide-file').onclick=()=>shareCollectionFile(activeSession,d.section,sessionKey.split('|')[1]);$('#slide-reset').onclick=()=>{sessionCounts[d.id]=0;write('session-'+sessionKey,sessionCounts);renderSessionSlide()};}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function shareText(text,title){try{if(navigator.share)await navigator.share({title,text});else{await navigator.clipboard.writeText(text);toast(t('نُسخ النص للمشاركة.','Text copied for sharing.'))}}catch(e){if(e.name!=='AbortError')toast(t('تعذرت المشاركة. يمكنك نسخ النص.','Sharing is unavailable. You can copy the text.'))}}
async function shareFile(path,title){try{const response=await fetch(path);if(!response.ok)throw Error();const blob=await response.blob(),file=new File([blob],path.split('/').pop(),{type:'application/pdf'});if(navigator.canShare?.({files:[file]}))await navigator.share({title,files:[file]});else{downloadBlob(blob,file.name);toast(t('نُزّل الملف؛ أرفقه في تطبيق التواصل الذي تختاره.','File downloaded. Attach it in your preferred messaging app.'))}}catch(e){if(e.name!=='AbortError')toast(t('تعذر فتح الملف. حاول مجددًا.','Could not open the file. Please retry.'))}}
let EXPORTS={};fetch('exports.json').then(r=>r.ok?r.json():{}).then(data=>EXPORTS=data).catch(()=>{});
function exportPath(section,category='الكل'){return EXPORTS[section+'|'+category]||EXPORTS[section+'|الكل']}
function shareCollectionFile(items,section,category){const path=exportPath(section,category);if(path)shareFile(path,t('ورد سكينة','Sakinah practice'));else openPrint(items,t('ورد سكينة','Sakinah practice'))}
function openPrint(items,title){const category=location.hash.split('/')[1]||'الكل',section=items[0]?.section,path=exportPath(section,decodeURIComponent(category));if(path){const a=document.createElement('a');a.href=path;a.download=path.split('/').pop();a.click();return}const win=window.open('','_blank');if(!win){toast(t('اسمح بفتح نافذة الطباعة لتنزيل PDF.','Allow the print window to save a PDF.'));return}win.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><title>${esc(title)} | سكينة</title><link href="https://fonts.googleapis.com/css2?family=Amiri&display=swap" rel="stylesheet"><style>@page{size:A5;margin:18mm}body{font:22px/2 Amiri;color:#173f35}header{text-align:center;border-bottom:1px solid #b39a63}img{width:75px}article{break-inside:avoid;border-bottom:1px solid #ddd;padding:15px 0}h1{font-size:35px}h2{font-size:23px}small{font-size:13px}footer{font-size:12px;text-align:center}button{padding:10px}@media print{button{display:none}}</style></head><body><header><img src="${new URL('assets/sakinah-emblem.png',location.href)}"><h1>سكينة</h1><h2>${esc(title)}</h2><small>جمع وإخراج سكينة · النصوص من مراجعها المبينة</small></header><button onclick="window.print()">طباعة / حفظ PDF</button>${items.map(d=>`<article><h2>${esc(d.title)}</h2><p>${esc(textOf(d))}</p><small>${esc(d.reference)} · ${counterLabel(d)}: ${ar(dhikrGoal(d))}</small></article>`).join('')}<footer>${location.origin} · مواد عامة للقراءة والذكر</footer></body></html>`);win.document.close()}
async function libraryPage(id,index=0){if(!BOOKS.length){$('#main').innerHTML=heading(t('مكتبة سكينة','Sakinah Library'),t('جارٍ تحميل الكتب…','Loading books…'));try{const response=await fetch('books.json');if(!response.ok)throw Error();BOOKS=await response.json()}catch{$('#main').innerHTML=heading(t('مكتبة سكينة','Sakinah Library'),t('تعذر تحميل المكتبة. أعد المحاولة.','Could not load the library. Please retry.'));return}if(currentRoute!=='library')return}if(typeof modernLibraryPage==='function')return modernLibraryPage(id,index);if(!id){$('#main').innerHTML=heading(t('كتبٌ تقرؤها بقلبك','A library for the heart'),t('اقرأ الأدعية كبطاقات متتابعة، أو نزّل نسختك وأرسلها لمن تحب. النصوص الأصلية بالعربية.','Read as slides, download a copy, or share it. Original devotional texts are in Arabic.'))+`<div class="books-grid">${BOOKS.map(b=>`<article class="book-card"><img class="book-emblem" src="assets/sakinah-emblem.png" alt=""><small>سَكِينَة · SAKINAH</small><h2>${esc(lang()==='en'?b.titleEn||b.title:b.title)}</h2><p>${ar(b.slides.length)} ${t('بطاقة قراءة','reading cards')}</p><a class="btn" href="#library/${b.id}/${read('bookPosition-'+b.id,0)}">${t('ابدأ القراءة','Start reading')} ←</a><div class="toolbar"><a class="chip" href="${esc(b.pdf)}" download>↓ PDF</a><button class="chip" data-book-share="${b.id}">${t('مشاركة الملف','Share file')}</button></div><p class="hint">${esc(b.sourceLabel||t('مادة مرفوعة، مع حفظ نسبتها الأصلية.','Provided material; original attribution retained.'))}</p></article>`).join('')}</div>`;document.querySelectorAll('[data-book-share]').forEach(btn=>btn.onclick=()=>{const b=BOOKS.find(b=>b.id===btn.dataset.bookShare);shareFile(b.pdf,b.title)});return}const b=BOOKS.find(b=>b.id===id);if(!b){if(!String(id).startsWith('reading-'))location.hash='library';return}index=Math.max(0,Math.min(b.slides.length-1,index));const slide=b.slides[index];$('#main').innerHTML=heading(esc(lang()==='en'?b.titleEn||b.title:b.title),t('قراءة متتابعة من المادة الأصلية، مع حفظ نسبتها.','Sequential reading from the original provided material, with attribution retained.'))+`<div class="slide-meta"><a class="chip" href="#library">→ ${t('المكتبة','Library')}</a><span>${ar(index+1)} / ${ar(b.slides.length)}</span><a class="chip" download href="${esc(b.pdf)}">↓ PDF</a><button class="chip" id="book-share-file">${t('مشاركة الملف','Share file')}</button></div><article class="prayer-slide book-slide"><h2>${esc(slide.title||b.title)}</h2>${slide.image?`<img class="original-page" src="${esc(slide.image)}" alt="${esc(slide.title||b.title)} — ${t('الصفحة الأصلية','original page')} ${ar(slide.sourcePage||index+1)}" loading="lazy">`:''}${slide.text&&!slide.imageOnly?`<div class="arabic-text" lang="ar" dir="rtl">${esc(slide.text).replaceAll('\n','<br>')}</div>`:''}<p class="hint">${slide.imageOnly?t('حُفظت الصفحة بصورتها الأصلية لصون النص؛ مشاركة الملف متاحة بدل نسخ نص غير دقيق.','This original page is shown as an image to preserve its text. Share the file instead of an unreliable transcription.'):''}</p><div class="toolbar">${!slide.imageOnly&&slide.text?`<button class="chip" id="book-share-text">${t('مشاركة النص','Share text')}</button>`:''}<button class="chip" id="book-save-slide">◆ ${t('حفظ موضع القراءة','Save reading position')}</button></div></article><div class="slide-navigation"><a class="btn secondary ${index===0?'disabled':''}" href="#library/${id}/${Math.max(0,index-1)}">→ ${t('السابق','Previous')}</a><a class="btn" href="${index===b.slides.length-1?'#library':`#library/${id}/${index+1}`}">${index===b.slides.length-1?t('العودة للمكتبة','Back to library'):t('التالي','Next')} ←</a></div>`;$('#book-share-file').onclick=()=>shareFile(b.pdf,b.title);$('#book-share-text')?.addEventListener('click',()=>shareText(slide.text,b.title));$('#book-save-slide').onclick=()=>{write('bookPosition-'+id,index);toast(t('حُفظ موضعك على هذا الجهاز.','Your place is saved on this device.'))}}
const PRAYER_CITIES=[['Muscat','مسقط',0],['Nizwa','نزوى',79],['Salalah','صلالة',56],['Sohar','صحار',52],['Sur','صور',57],['Ibri','عبري',61],['Rustaq','الرستاق',15]];
const PRAYER_NAMES=[['Fajr','الفجر'],['Sunrise','الشروق'],['Dhuhr','الظهر'],['Asr','العصر'],['Maghrib','المغرب'],['Isha','العشاء']];
let calendarMonth=new Date().getMonth(),calendarYear=new Date().getFullYear(),prayerAbort=null,prayerClock=null,prayerFocusDay=new Date().getDate();
function maraCityId(city=read('prayerCity','Muscat')){return PRAYER_CITIES.find(([en])=>en===city)?.[2]??0}
function enrichPrayerHijri(days,year,month){return (days||[]).map((day,i)=>{if(day?.date?.hijri)return day;const date=new Date(year,month-1,i+1);const parts=new Intl.DateTimeFormat('en-u-ca-islamic-umalqura',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Muscat'}).formatToParts(date);const get=type=>parts.find(p=>p.type===type)?.value||'';const arParts=new Intl.DateTimeFormat('ar-OM-u-ca-islamic-umalqura',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Muscat'}).formatToParts(date);const getAr=type=>arParts.find(p=>p.type===type)?.value||'';return{...day,date:{...day.date,hijri:{day:get('day'),year:get('year'),month:{en:get('month'),ar:getAr('month')}}}}})}
async function loadMonthPrayers(city,year,month,signal,method=read('prayerMethod','8')){const cityId=maraCityId(city),cacheKey='mara-'+cityId+'-'+year+'-'+month;const cached=read(cacheKey,null);if((Array.isArray(cached)&&cached.length)||cached?.data?.length){const days=Array.isArray(cached)?cached:cached.data;return{data:enrichPrayerHijri(days,year,month),source:cached.source||'mara'}}const accept=payload=>{const days=payload?.data||payload;if(!Array.isArray(days)||!days.length)throw Error('empty');write(cacheKey,{source:payload?.source||'mara',data:days});return{data:enrichPrayerHijri(days,year,month),source:payload?.source||'mara'}};try{const local=await fetch('prayers/mara/'+cityId+'/'+year+'-'+month+'.json',{signal});if(local.ok)return accept(await local.json())}catch(e){if(e.name==='AbortError')throw e}try{const live=await fetch('/api/mara-prayers?year='+year+'&month='+month+'&cityId='+cityId,{signal});if(live.ok)return accept(await live.json())}catch(e){if(e.name==='AbortError')throw e}const aladhanKey='prayers-'+city+'-'+method+'-'+year+'-'+(month-1);let fallback=read(aladhanKey,null);if(!fallback){const response=await fetch('https://api.aladhan.com/v1/calendarByCity?city='+encodeURIComponent(city)+'&country=Oman&method='+method+'&month='+month+'&year='+year,{signal});if(!response.ok)throw Error('aladhan');const result=await response.json();if(!Array.isArray(result.data))throw Error('aladhan-data');fallback=result.data;write(aladhanKey,fallback)}return{data:fallback,source:'aladhan'}}
function prayerClockNow(){return new Intl.DateTimeFormat(lang()==='en'?'en-GB':'ar-OM',{timeZone:'Asia/Muscat',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date())}
function prayerHHMM(day,key){return day?.timings?.[key]?.split(' ')[0]||'—'}
function prayerWeekday(date){return new Intl.DateTimeFormat(lang()==='en'?'en-GB':'ar-OM',{weekday:'long',timeZone:'Asia/Muscat'}).format(date)}
function prayerGregorian(date){return new Intl.DateTimeFormat(lang()==='en'?'en-CA':'en-CA',{timeZone:'Asia/Muscat',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
function prayerHijriLabel(day){const h=day?.date?.hijri;if(!h)return '';return lang()==='en'?`${h.day} ${h.month.en} ${h.year}`:`${ar(h.day)} ${h.month.ar} ${ar(h.year)}`}
function muscatWallMs(y,m,d,hhmm){const [H,M]=String(hhmm||'').split(':').map(Number);if(!Number.isFinite(H)||!Number.isFinite(M))return NaN;return Date.UTC(y,m-1,d,H-4,M,0)}
function prayerDayStatus(day,y,m,d,now=Date.now()){const slots=PRAYER_NAMES.map(([en,arName])=>({en,arName,at:muscatWallMs(y,m,d,prayerHHMM(day,en))})).filter(s=>Number.isFinite(s.at));let prev=null,next=null;for(const s of slots){if(s.at<=now)prev=s;else if(!next)next=s}return{slots,prev,next,sincePrev:prev?now-prev.at:null,untilNext:next?next.at-now:null}}
function formatPrayerSpan(ms){const total=Math.max(0,Math.floor(ms/60000)),h=Math.floor(total/60),m=total%60;if(lang()==='en'){if(h&&m)return h+'h '+m+'m';if(h)return h+'h';return m+'m'}if(h&&m)return ar(h)+' '+t('ساعة','h')+' '+t('و','and')+' '+ar(m)+' '+t('دقيقة','min');if(h)return ar(h)+' '+t('ساعة','h');return ar(m)+' '+t('دقيقة','min')}
function weekStartSaturday(date){const d=new Date(date.getFullYear(),date.getMonth(),date.getDate()),since=(d.getDay()+1)%7;d.setDate(d.getDate()-since);return d}
function renderPrayerDaily(day,y,m,d){if(!day)return `<p>${t('لا تتوفر مواقيت لهذا اليوم.','No prayer times for this day.')}</p>`;const status=prayerDayStatus(day,y,m,d),date=new Date(y,m-1,d),label=prayerWeekday(date)+' · '+prayerGregorian(date);return `<div class="prayer-clock"><span>${t('الوقت الحالي','Current time')}</span><strong id="prayer-live-clock" dir="ltr">${prayerClockNow()}</strong></div><h3 class="prayer-day-title">${esc(label)}${prayerHijriLabel(day)?` · ${esc(prayerHijriLabel(day))}`:''}</h3><div class="prayer-smart-row"><article class="smart-next"><span>${t('الصلاة القادمة','Next prayer')}</span><strong>${status.next?(lang()==='en'?status.next.en:status.next.arName):'—'}</strong><b>${status.next?t('بعد','in')+' '+formatPrayerSpan(status.untilNext):'—'}</b></article><article class="smart-prev"><span>${t('الصلاة المنصرمة','Previous prayer')}</span><strong>${status.prev?(lang()==='en'?status.prev.en:status.prev.arName):'—'}</strong><b>${status.prev?t('منذ','since')+' '+formatPrayerSpan(status.sincePrev):'—'}</b></article></div><div class="prayer-day-list">${status.slots.map(s=>{const state=status.next?.en===s.en?'is-next':status.prev?.en===s.en?'is-prev':'';const rel=s.at>Date.now()?t('بعد','in')+' '+formatPrayerSpan(s.at-Date.now()):t('منذ','since')+' '+formatPrayerSpan(Date.now()-s.at);return `<article class="${state}"><small>${lang()==='en'?s.en:s.arName}</small><strong dir="ltr">${esc(prayerHHMM(day,s.en))}</strong><b>${rel}</b></article>`}).join('')}</div>`}
function renderPrayerTable(rows,todayKey){return `<div class="prayer-table-wrap"><table class="prayer-schedule-table"><thead><tr><th>${t('اليوم','Day')}</th><th>${t('التاريخ','Date')}</th>${PRAYER_NAMES.map(([,arName],i)=>`<th>${lang()==='en'?PRAYER_NAMES[i][0]:arName}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr class="${r.key===todayKey?'is-today':''}"><td>${esc(r.weekday)}</td><td><span dir="ltr">${esc(r.gregorian)}</span>${r.hijri?`<small>${esc(r.hijri)}</small>`:''}</td>${PRAYER_NAMES.map(([en])=>`<td dir="ltr">${esc(r.times[en]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function showPrayers(day,target){if(!day||!target)return;const g=day.date?.gregorian,y=Number(g?.year)||calendarYear,m=Number(g?.month)||calendarMonth+1,d=Number(g?.day)||1;target.innerHTML=renderPrayerDaily(day,y,m,d)}
