const baseTasbih=tasbih;tasbih=function(){baseTasbih();$('.tasbih').insertAdjacentHTML('beforeend',`<label class="auto-option" style="justify-content:center"><input id="tasbih-auto" type="checkbox" ${read('autoAdvance',true)?'checked':''}>${t('الانتقال للذكر التالي عند اكتمال العدد','Continue to the next remembrance when the goal is complete')}</label>`);$('#tasbih-auto').onchange=e=>write('autoAdvance',e.target.checked);$('#tasbih-tap').addEventListener('click',()=>{const goal=Number($('#tasbih-goal').value);if(tasbihCount===goal){recordActivity('dhikr',{id:'tasbih',title:tasbihDhikr,count:goal});if(read('autoAdvance',true)){const selected=$('#tasbih-dhikr'),next=selected.selectedIndex+1;if(next<selected.options.length){const nextValue=selected.options[next].value;$('#tasbih-tap').disabled=true;setTimeout(()=>{if(currentRoute!=='tasbih')return;tasbihDhikr=nextValue;tasbihCount=0;write('tasbihDhikr',tasbihDhikr);write('tasbih',0);tasbih();$('#tasbih-goal').value=String(goal);toast(t('انتقلت إلى الذكر التالي.','Continued to the next remembrance.'))},550)}else toast(t('اكتملت دورة الأذكار. تقبّل الله منك.','Your remembrance cycle is complete.'))}}})};
function openPageZoom(image){let dialog=$('#page-zoom');if(!dialog){document.body.insertAdjacentHTML('beforeend',`<dialog id="page-zoom"><div class="dialog-top"><h2>${t('تكبير الصفحة','Zoom page')}</h2><button class="icon-button" id="zoom-close" aria-label="${t('إغلاق','Close')}">×</button></div><label class="zoom-control">${t('حجم العرض','Zoom level')}<input id="zoom-range" type="range" min="100" max="350" value="170"><span id="zoom-percent">170%</span></label><div id="zoom-scroller"><img id="zoom-image" alt=""></div></dialog>`);dialog=$('#page-zoom');$('#zoom-close').onclick=()=>dialog.close();$('#zoom-range').oninput=e=>{$('#zoom-image').style.width=e.target.value+'%';$('#zoom-percent').textContent=e.target.value+'%'}}$('#zoom-image').src=image.src;$('#zoom-image').alt=image.alt;$('#zoom-image').style.width='170%';$('#zoom-range').value='170';$('#zoom-percent').textContent='170%';dialog.showModal()}
document.addEventListener('click',e=>{const image=e.target.closest('.original-page');if(image)openPageZoom(image)});
const arabicSources=sources;sources=function(){if(lang()!=='en'){arabicSources();return}$('#main').innerHTML=heading('Sakinah, from Oman to the heart','An independent Arabic and English reading experience with an Omani spirit and Ibadi identity.','ABOUT & SOURCES')+`<div class="source-grid"><article class="source-card"><h2>Identity and editorial approach</h2><p>Quranic text, hadith and general supplications are distinguished. References accompany the texts. Sakinah does not claim that the hadith collection has received an Ibadi scholarly review or official endorsement. Consult qualified scholars on matters of doctrine and jurisprudence.</p><a href="https://iftaa.mara.gov.om/" target="_blank" rel="noopener">Oman Ifta Office ↗</a></article><article class="source-card"><h2>Quran text and page images</h2><p>The complete quran-uthmani edition is stored locally, containing 114 surahs and 6,236 verses. Original page images load from the King Saud University Ayat project, which credits the King Fahd Quran Printing Complex. The local text view remains available if images cannot load.</p><a href="https://alquran.cloud/api" target="_blank" rel="noopener">Al Quran Cloud</a> · <a href="https://tanzil.net/" target="_blank" rel="noopener">Tanzil</a> · <a href="QURAN-LICENSE.txt">Text license</a> · <a href="https://quran.ksu.edu.sa/" target="_blank" rel="noopener">Ayat page images</a></article><article class="source-card"><h2>Uploaded devotional books</h2><p>The five provided books retain their original page content and visible source attributions. Sakinah supplies a reading edition, cover and layout, without claiming authorship. Original page images preserve Arabic text where reliable extraction was not possible. Religious texts and uploaded originals remain Arabic in both interface languages.</p><a href="#library">Open the reading library →</a></article><article class="source-card"><h2>Personal goals and reminders</h2><p>Sourced repetition counts are distinguished from suggested personal goals. A numerical goal does not establish special religious merit. Browser reminders operate while the site is open, with permission; import the provided calendar reminder for alerts when the site is closed. Your calendar app controls those alerts.</p></article><article class="source-card"><h2>Privacy and account data</h2><p>Public reading requires no account. Guest activity stays in the browser. Optional ChatGPT sign-in enables private storage of account visits, completed dhikr, pages marked as read, a daily plan and Quran bookmark. Scrolling alone is not recorded as completed reading. Device preferences and favorites remain local. Your account page shows your latest 2,500 activities from the last 90 days.</p><p>Fonts, Quran page images, recitations and prayer-time requests connect to their named providers. No advertising or analytics code has been added to this site.</p></article><article class="source-card"><h2>Prayer times and image rights</h2><p>Prayer times use AlAdhan’s calculated data for the selected Omani city and calculation method. They are estimates, not an official Omani timetable. Local moon sighting can differ from the calculated Hijri calendar. Follow the local mosque and Ministry guidance.</p><a href="https://www.mara.gov.om/arabic/calendar.html" target="_blank" rel="noopener">Oman official calendar</a> · <a href="https://aladhan.com/prayer-times-api" target="_blank" rel="noopener">AlAdhan</a><p>Photograph attributions and Creative Commons license links accompany the Omani landmark gallery.</p><a href="#landmarks">Photograph credits →</a></article></div>`};
